def budget_context(items, budget):
    packed, dropped = [], []
    used = 0
    for it in sorted(items, key=lambda x: x["priority"]):
        if used + it["tokens"] <= budget:
            packed.append(it)
            used += it["tokens"]
        else:
            dropped.append(it)
    return packed, dropped

import json

def parse_json(output):
    try:
        return json.loads(output)
    except (json.JSONDecodeError, ValueError):
        return None

def evaluate(output, required):
    data = parse_json(output)
    if not isinstance(data, dict):
        return (False, len(required))
    missing = sum(1 for k in required if k not in data or data[k] is None)
    return (missing == 0, missing)

def ab_report(results_a, results_b):
    ra = round(sum(results_a) / len(results_a), 2) if results_a else 0.0
    rb = round(sum(results_b) / len(results_b), 2) if results_b else 0.0
    return (ra, rb, round(rb - ra, 2))
